// Column widths of code points as programs count them (wcwidth()): 2 for East Asian Wide and
// Fullwidth characters (CJK, Hangul syllables, emoji with an emoji presentation), 0 for combining
// marks, format characters and the Hangul medial vowels and final consonants, 1 for the rest.
// Tables: charwidth_table_p.h, generated by scripts/term-width-table.py (Unicode 16).
#pragma once

namespace brulion::term {

/// The columns `cp` takes: 0 (it joins the character before it), 1 or 2. Control characters
/// (C0, DEL, C1) and code points outside Unicode are 1 here: the parser never prints them.
int charWidth(char32_t cp);

} // namespace brulion::term
